"""Start real Valhalla with a config generated by the pinned installed binary."""
import json
import os
from pathlib import Path
import subprocess

graph=Path('/custom_files/valhalla_tiles.tar')
if not graph.is_file():raise SystemExit('Road graph missing: run runtime-setup first')
config=json.loads(subprocess.check_output(['valhalla_build_config'],text=True))
config['mjolnir']['tile_extract']=str(graph)
config['mjolnir']['tile_dir']='/custom_files/valhalla_tiles'
config['mjolnir']['concurrency']=4
file=Path('/tmp/beego-complete-valhalla.json');file.write_text(json.dumps(config))
os.execvp('valhalla_service',['valhalla_service',str(file),'4'])
